    private static Optional<String> extractTableCodeFromJson(String json) {
        if (json == null || json.isBlank()) {
            return Optional.empty();
        }
        String key = "\"tableCode\"";
        int keyIdx = json.indexOf(key);
        if (keyIdx < 0) {
            return Optional.empty();
        }
        int colonIdx = json.indexOf(':', keyIdx + key.length());
        int firstQuote = colonIdx < 0 ? -1 : json.indexOf('"', colonIdx + 1);
        int secondQuote = firstQuote < 0 ? -1 : json.indexOf('"', firstQuote + 1);
        if (firstQuote < 0 || secondQuote <= firstQuote) {
            return Optional.empty();
        }
        return Optional.of(json.substring(firstQuote + 1, secondQuote).trim());
    }"

